function w121RemindPairMember(pairId,memberId,name){w121Call('remindMentorOneToOneMember',{pairId:pairId,memberId:memberId,dryRun:true},function(pre){if(!pre.ok)return;if(pre.allowed===false){toast('ยังส่งไม่ได้: '+(pre.reason||'ติด Message Guard'),'warn');return;}openLineSendReview({title:'ตรวจข้อความเตือน 1-2-1',audience:name||pre.audience||'สมาชิก',message:pre.message||'',onConfirm:function(edited,finish){w121Call('remindMentorOneToOneMember',{pairId:pairId,memberId:memberId,dryRun:false,confirmed:true,customMessage:edited},function(r){finish();if(r.ok){toast(r.skipped?'ข้อความนี้เคยส่งแล้ววันนี้':'ส่งข้อความเตือนแล้ว','ok');w121OpenPairAction(pairId);}});}});});}
function w121PairOperation(pairId,operation){var reason='',payload={pairId:pairId,operation:operation};if(operation==='cancel'){reason=prompt('เหตุผลที่ยกเลิกคู่ (จำเป็น)')||'';if(!reason)return;if(!confirm('ยืนยันยกเลิกคู่นี้?\nข้อมูลเดิมยังอยู่ใน Audit/History'))return;payload.reason=reason;}if(operation==='assign'){payload.ownerRole=prompt('Role ผู้รับผิดชอบ เช่น toomtam, aof หรือ mc','mc')||'';if(!payload.ownerRole)return;}if(operation==='snooze'){var days=Number(prompt('ติดตามอีกกี่วัน?', '2')||0);if(!days)return;payload.snoozedUntil=new Date(Date.now()+days*86400000).toISOString();}w121Call('updateOneToOnePairOperation',payload,function(r){if(r.ok){toast('อัปเดตการดูแลคู่แล้ว','ok');operation==='cancel'?w121ClosePairAction():w121OpenPairAction(pairId);w121LoadQueues();}});}
function w121ScheduleOperation(pairId,scheduleId,operation){var reason=prompt(operation==='reschedule'?'เหตุผลและวันใหม่จะถูกบันทึก':'บันทึกเหตุผล','')||'',payload={pairId:pairId,scheduleId:scheduleId,operation:operation,reason:reason};if(operation==='reschedule'){var value=prompt('วันเวลาใหม่ รูปแบบ YYYY-MM-DDTHH:mm');if(!value)return;var next=new Date(value);if(!Number.isFinite(next.getTime())||next<=new Date()){toast('กรุณาระบุวันเวลาใหม่ในอนาคต','warn');return;}payload.startsAt=next.toISOString();}if(!confirm('ยืนยันอัปเดตนัดหมาย?'))return;w121Call('updateOneToOneScheduleOperation',payload,function(r){if(r.ok){toast('อัปเดตนัดหมายแล้ว · รอทั้งคู่ยืนยันเวลาใหม่','ok');w121OpenPairAction(pairId);}});}
function w121UpdateReferral(id){var labels={connection_identified:'นึกถึง Connection',permission_requested:'ขออนุญาตแล้ว',permission_granted:'ได้รับอนุญาต',introduction_sent:'ส่ง Introduction แล้ว',meeting_booked:'นัดหมายแล้ว',referral_created:'เกิด Referral',collaboration:'เกิด Collaboration',won:'เกิดผลสำเร็จ',not_ready:'ยังไม่พร้อม',not_a_fit:'ยังไม่เหมาะ',learning_only:'ได้เรียนรู้'};var stage=prompt('ระบุขั้นต่อไป:\n'+Object.keys(labels).map(function(k){return k+' = '+labels[k];}).join('\n'),'connection_identified');if(!stage||!labels[stage])return;var notes=prompt('หมายเหตุผลลัพธ์ (ห้ามใส่ข้อมูลบุคคลที่สามโดยไม่มี Consent)','')||'';w121Call('updateOneToOneReferralOutcome',{id:id,stage:stage,notes:notes},function(r){if(r.ok){toast('อัปเดต Referral Outcome แล้ว','ok');w121LoadOperations();}});}
function w121RetryDelivery(id){if(!confirm('Retry ข้อความนี้?\n\nระบบจะใช้ Payload เดิม ตรวจ Quota/Cooldown และสร้าง Delivery Log ใหม่'))return;w121Call('retryOneToOneDelivery',{id:id,confirmed:true},function(r){if(r.ok){toast(r.skipped?'ข้อความซ้ำถูกข้าม':'Retry สำเร็จ','ok');w121LoadOperations();w121LoadMessageControl();}});}
