function w121LoadMessageControl(){w121Call('getOneToOneMessageControl',{},function(r){if(!r.ok)return;var root=document.getElementById('w121-message-control'),budget=(r.budgets||[]).find(function(x){return x.module==='one_to_one';})||{},cap=Number(budget.monthly_hard_cap||3000),pct=cap?Math.round(Number(r.sent||0)/cap*100):0;var reasons=Object.entries(r.suppressed||{}).map(function(x){return'<div style="display:flex;justify-content:space-between;font-size:11px;padding:7px 0;border-bottom:1px solid var(--bd)"><span>'+esc(x[0])+'</span><b>'+x[1]+'</b></div>';}).join('')||'<div class="w121-panel-sub" style="margin-top:8px">ยังไม่มีข้อความถูก Suppress</div>';var recipients=(r.topRecipients||[]).map(function(x){return'<div style="display:flex;justify-content:space-between;font-size:11px;padding:7px 0;border-bottom:1px solid var(--bd)"><span>'+esc(x.name)+'</span><b>'+x.count+'</b></div>';}).join('')||'<div class="w121-panel-sub" style="margin-top:8px">ยังไม่มีข้อมูลเดือนนี้</div>';root.innerHTML='<div class="w121-overview-grid"><div class="w121-kpi"><small>ส่งแล้วเดือนนี้</small><b>'+Number(r.sent||0).toLocaleString()+'</b><span>'+pct+'% ของงบ 1-2-1</span></div><div class="w121-kpi"><small>Forecast สิ้นเดือน</small><b>'+Number(r.forecast||0).toLocaleString()+'</b><span>Hard cap '+cap.toLocaleString()+'</span></div><div class="w121-kpi"><small>Suppressed</small><b>'+Number((r.byStatus||{}).skipped||0).toLocaleString()+'</b><span>ป้องกันข้อความที่ไม่ควรส่ง</span></div><div class="w121-kpi"><small>Failed</small><b style="color:'+(Number((r.byStatus||{}).failed||0)?'var(--re)':'var(--gr)')+'">'+Number((r.byStatus||{}).failed||0)+'</b><span>ตรวจ Retry Queue</span></div></div><div class="m360g" style="margin-top:12px"><div class="w121-panel"><div class="w121-panel-title">Suppression Reasons</div>'+reasons+'</div><div class="w121-panel"><div class="w121-panel-title">ผู้รับข้อความมากที่สุด</div>'+recipients+'</div></div>';});}
function w121Import(){
  var file=document.getElementById('w121-file').files[0],status=document.getElementById('w121-import-status');
  if(!file&&!W121.csv){toast('กรุณาเลือกไฟล์ CSV','warn');return;}
  function submit(text,name){W121.csv=text;W121.fileName=name;status.textContent='⏳ กำลังตรวจสอบไฟล์และฐานสมาชิก...';w121Call('importWeekly121Csv',{csv:text,fileName:name,meetingDate:document.getElementById('w121-date').value,repeatWindowWeeks:Number(document.getElementById('w121-window').value||12),messageTemplateKey:document.getElementById('w121-template').value},function(r){
    if(!r.ok){status.textContent='❌ '+(r.error||'');return;}
    if(r.needsDate){var sel=document.getElementById('w121-date');sel.innerHTML='<option value="">เลือกวันที่</option>'+r.dates.map(function(d){return '<option value="'+esc(d)+'">'+esc(d)+'</option>';}).join('');status.textContent='ไฟล์มีหลายวัน กรุณาเลือกวันที่แล้วกดตรวจสอบอีกครั้ง';return;}
    W121.roundId=r.roundId;W121.rows=r.rows||[];W121.memberOptions=r.memberOptions||[];W121.swap=null;status.textContent='✅ สร้างร่างแล้ว · '+r.meetingDate;w121RenderImport(r);w121SetStep(2);w121LoadHistory(true);
  });}
  if(file){if(file.size>2*1024*1024){toast('ไฟล์มีขนาดเกิน 2 MB','warn');return;}var reader=new FileReader();reader.onload=function(e){submit(String(e.target.result||''),file.name);};reader.readAsText(file,'UTF-8');}else submit(W121.csv,W121.fileName);
}
function w121RenderImport(r){
  document.getElementById('w121-work').style.display='';var s=r.summary||{};
  document.getElementById('w121-summary').innerHTML='<div class="w121-stats">'+[['พร้อม',s.ready,'#06C755'],['ไม่มี LINE',s.no_line,'#fbbf24'],['ไม่พบ',s.not_found,'var(--re)'],['ข้อมูลซ้ำ',s.duplicate,'var(--ye)'],['ผู้มาแทน',s.substitute,'#818cf8'],['ต้องเลือก',s.ambiguous,'#fb7185']].map(function(x){return '<div class="w121-stat"><b style="color:'+x[2]+'">'+Number(x[1]||0)+'</b><span>'+x[0]+'</span></div>';}).join('')+'</div>';
  var abnormal=(r.rows||[]).filter(function(x){return x.status!=='ready';});
  var issues=document.getElementById('w121-issues');
  var importStatus=document.getElementById('w121-import-status');if(importStatus){var ready=Number(s.ready||0),total=(r.rows||[]).length;importStatus.className='w121-inline-status '+(!abnormal.length?'ready':'blocked');importStatus.textContent=!abnormal.length?'✅ พร้อม '+ready+' / '+total+' คน · ขั้นต่อไปกด “2. สุ่มคู่”':'⚠️ พร้อม '+ready+' / '+total+' คน · แก้รายการด้านล่างให้ครบก่อนสุ่ม';}
  if(!abnormal.length){issues.innerHTML='<div style="color:#06C755;font-size:11px;margin-top:10px">✓ รายชื่อทั้งหมดพร้อมจับคู่ · ไปขั้นที่ 3 ได้เลย</div>';return;}
  issues.innerHTML='<div style="margin-top:12px;border:1px solid var(--bd);border-radius:12px;overflow:hidden">'+abnormal.slice(0,80).map(function(x){var canResolve=x.status==='not_found'||x.status==='ambiguous'||x.status==='no_line';var opts='<option value="">เลือกสมาชิกในฐานข้อมูล…</option>'+W121.memberOptions.map(function(m){return '<option value="'+esc(m.id)+'">'+esc(m.name)+(m.nickname?' ('+esc(m.nickname)+')':'')+'</option>';}).join('');return '<div class="w121-issue"><div><b>แถว '+x.rowNumber+' · '+esc(x.fullName||'ไม่ระบุชื่อ')+'</b><div style="color:var(--sub);margin-top:2px">'+esc(x.message||x.status)+'</div></div>'+(canResolve?'<select class="w121-control" id="w121-resolve-'+x.rowNumber+'" style="margin:0">'+opts+'</select><button class="bsm" onclick="w121Resolve('+x.rowNumber+')">ยืนยันคนนี้</button>':'<div style="color:var(--sub)">ไม่เข้าสุ่มอัตโนมัติ</div><span></span>')+'</div>';}).join('')+'</div>';
}
function w121SetStep(n){document.querySelectorAll('#mc-w121 .w121-step').forEach(function(el,i){el.classList.toggle('active',i<n);});}
function w121UpdateActionFlow(){var pairs=W121.pairs||[],hasPairs=pairs.length>0,allLocked=hasPairs&&pairs.every(function(p){return Boolean(p.is_locked);}),previewReady=w121HasValidPreview(),states=[hasPairs,allLocked,previewReady,false],current=!hasPairs?0:!allLocked?1:!previewReady?2:3;['w121-action-generate','w121-lock-all','w121-action-preview','w121-action-send'].forEach(function(id,i){var el=document.getElementById(id);if(!el)return;el.classList.toggle('done',states[i]);el.classList.toggle('current',i===current);el.setAttribute('aria-current',i===current?'step':'false');});if(hasPairs)w121SetStep(previewReady?4:allLocked?3:2);}
function w121Resolve(row){var el=document.getElementById('w121-resolve-'+row),memberId=el&&el.value;if(!memberId){toast('กรุณาเลือกสมาชิก','warn');return;}w121Call('resolveWeekly121ImportRow',{roundId:W121.roundId,rowNumber:row,memberId:memberId},function(r){if(r.ok){toast(r.status==='ready'?'ยืนยันสมาชิกแล้ว':'ยืนยันแล้ว แต่สมาชิกยังไม่มี LINE',r.status==='ready'?'ok':'warn');var issue=el.closest('.w121-issue');if(issue)issue.style.display='none';}});}
