function w121RenderRound(r){W121.pairs=r.pairs||[];W121.previews=r.previews||[];if(r.round&&r.round.message_template_key){document.getElementById('w121-template').value=r.round.message_template_key;w121TemplateChangedHelpOnly();}var el=document.getElementById('w121-pairs'),waiting=r.waiting||[];if(!W121.pairs.length){el.innerHTML='<div class="w121-empty" style="grid-column:1/-1">🎲 ยังไม่มีผลจับคู่<br><span style="font-size:10px">เลือกวิธีจับคู่แล้วกด “สุ่มคู่” เพื่อเริ่มออกแบบบทสนทนา</span></div>';w121UpdateActionFlow();return;}el.innerHTML=W121.pairs.map(function(p,i){var ms=p.members||[],reasons=p.matchReasons||[];return '<div class="w121-pair '+(p.is_locked?'locked':'')+'"><div class="w121-pair-head"><span class="w121-pair-no">PAIR '+(i+1)+'</span>'+(ms.length===3?'<span style="font-size:9px;color:#c4b5fd">LEGACY GROUP</span>':'')+'<span style="flex:1"></span><button class="w121-icon-btn" onclick="w121Lock(\''+p.id+'\','+(!p.is_locked)+')">'+(p.is_locked?'🔒 ล็อกแล้ว':'🔓 ล็อกคู่')+'</button></div><div class="w121-reason">'+reasons.map(function(x){return '<span>✦ '+esc(x)+'</span>';}).join('')+'</div>'+ms.map(function(m){var d=m.delivery||{},ds=String(d.status||''),dc=ds==='sent'?'#06C755':ds==='failed'?'var(--re)':m.lineUserId?'#60a5fa':'#64748b';var initial=String(m.nickname||m.name||'?').trim().charAt(0).toUpperCase();return '<div class="w121-member"><div class="w121-avatar">'+esc(initial)+'</div><div style="min-width:0;flex:1"><div class="w121-member-name">'+esc(m.name||'')+(m.nickname?' <span style="font-weight:500;color:var(--sub)">· '+esc(m.nickname)+'</span>':'')+'</div><div class="w121-member-meta">'+esc(m.business||m.profession||m.company_name||'ยังไม่มีข้อมูลธุรกิจ')+' · ทีม '+esc(m.mentor_team||'—')+'</div><button class="w121-icon-btn" style="margin-top:5px" onclick="w121EditBusiness(\''+m.id+'\')">✏️ ข้อมูลธุรกิจ</button><div style="font-size:9px;color:'+dc+';margin-top:4px"><span class="w121-dot" style="background:'+dc+'"></span>'+(ds==='sent'?'ส่ง LINE แล้ว':ds==='failed'?'ส่งไม่สำเร็จ · ครั้งที่ '+Number(d.attempts||1):m.lineUserId?'LINE พร้อม':'ยังไม่เชื่อม LINE')+'</div></div><div class="w121-member-actions"><button class="w121-icon-btn '+(W121.swap&&W121.swap.memberId===String(m.id)?'selected':'')+'" onclick="w121SelectSwap(\''+p.id+'\',\''+m.id+'\')" title="เลือกเพื่อสลับคู่">⇄</button><button class="w121-icon-btn" onclick="w121RemoveMember(\''+p.id+'\',\''+m.id+'\')" title="นำออกจากรอบ">✕</button></div></div>';}).join('')+'</div>';}).join('')+(waiting.length?'<div class="w121-waiting" style="grid-column:1/-1"><b style="font-size:11px;color:#fbbf24">Waiting List · ไม่ถือเป็นความล้มเหลว</b>'+waiting.map(function(w){var m=w.member||{};return '<div style="font-size:11px;margin-top:6px">'+esc(m.name||'สมาชิก')+' · Priority ทบ '+Number(w.priority_points||1)+' · จะได้สิทธิ์จับคู่ก่อนในรอบถัดไป</div>';}).join('')+'</div>':'');w121UpdateActionFlow();}
function w121TemplateChangedHelpOnly(){var el=document.getElementById('w121-template'),help={growth_opportunity:'ครบทั้งธุรกิจ Looking for คำถามเปิดบทสนทนา และภารกิจ Referral',warm_connection:'เน้นความสัมพันธ์และการฟัง เหมาะกับสมาชิกใหม่หรือคู่ที่ยังไม่สนิท',referral_focus:'เจาะลูกค้าในอุดมคติ Referral Trigger และ Connection ที่ช่วยกันได้',story_trust:'ใช้เรื่องราวและจุดเปลี่ยนสร้างความไว้ใจ ก่อนต่อยอดธุรกิจ',quick_action:'สั้น กระชับ มีขั้นตอนชัด เหมาะกับสัปดาห์ที่ทุกคนเวลาน้อย'};W121.templateKey=el.value;document.getElementById('w121-template-help').textContent=help[el.value]||'';}
function w121EditBusiness(memberId){var member=null;W121.pairs.some(function(p){member=(p.members||[]).find(function(m){return String(m.id)===String(memberId);});return Boolean(member);});if(!member)return;var description=prompt('Business Profile ของ '+member.name+'\nอธิบายว่าทำธุรกิจอะไร และช่วยลูกค้าแบบไหน',member.business||'');if(description===null)return;var profession=prompt('อาชีพ / Profession',member.profession||'');if(profession===null)return;var company=prompt('ชื่อบริษัท / Company Name',member.company_name||'');if(company===null)return;w121Call('saveOneToOneBusinessProfile',{memberId:memberId,description:description,profession:profession,companyName:company},function(r){if(r.ok){member.business=description||profession||company;member.profession=profession;member.company_name=company;toast('บันทึกข้อมูลธุรกิจของ '+member.name+' แล้ว','ok');w121Open(W121.roundId);}});}
function w121FindMember(pairId,memberId){var pair=W121.pairs.find(function(p){return String(p.id)===String(pairId);});return pair&&(pair.members||[]).find(function(m){return String(m.id)===String(memberId);});}
function w121SelectSwap(pairId,memberId){var member=w121FindMember(pairId,memberId),name=member?member.name:'สมาชิก',note=document.getElementById('w121-swap-note');if(!W121.swap){W121.swap={pairId:pairId,memberId:memberId,name:name};note.style.display='';note.textContent='เลือก '+name+' แล้ว — คลิก ⇄ ที่สมาชิกอีกคู่เพื่อสลับ';w121RenderRound({pairs:W121.pairs,previews:W121.previews});return;}if(W121.swap.pairId===pairId){W121.swap=null;note.style.display='none';w121RenderRound({pairs:W121.pairs,previews:W121.previews});return;}var first=W121.swap;if(!confirm('สลับ '+first.name+' กับ '+name+'?'))return;w121Call('swapWeekly121Members',{roundId:W121.roundId,firstPairId:first.pairId,firstMemberId:first.memberId,secondPairId:pairId,secondMemberId:memberId},function(r){if(r.ok){W121.swap=null;note.style.display='none';toast('สลับสมาชิกแล้ว','ok');w121RenderRound(r);}});}
function w121RemoveMember(pairId,memberId){var member=w121FindMember(pairId,memberId),name=member?member.name:'สมาชิก';if(!confirm('นำ '+name+' ออกจากรอบจับคู่นี้?\nสมาชิกคนนี้จะไม่ถูกนำกลับมาเมื่อสุ่มใหม่'))return;w121Call('removeWeekly121Member',{roundId:W121.roundId,pairId:pairId,memberId:memberId},function(r){if(r.ok){toast('นำ '+name+' ออกจากรอบแล้ว','ok');w121RenderRound(r);}});}
function w121Lock(id,locked){w121InvalidatePreview();w121Call('setWeekly121PairLock',{pairId:id,locked:locked},function(r){if(r.ok)w121Open(W121.roundId);});}
function w121LockAll(locked){if(!W121.roundId||!(W121.pairs||[]).length){toast('กรุณากด “1. สุ่มคู่” ก่อน','warn');return;}w121InvalidatePreview();w121Call('setWeekly121RoundLock',{roundId:W121.roundId,locked:locked},function(r){if(r.ok){toast(locked?'ล็อกคู่ทั้งหมดแล้ว · ขั้นต่อไปตรวจ Preview':'ปลดล็อกทั้งหมดแล้ว','ok');w121Open(W121.roundId);}});}
function w121DryRun(){if(!W121.roundId){toast('กรุณาอัปโหลดและตรวจรายชื่อก่อน','warn');return;}if(!(W121.pairs||[]).length){toast('กรุณากด “1. สุ่มคู่” ก่อน','warn');return;}if(!W121.pairs.every(function(p){return Boolean(p.is_locked);})){toast('กรุณากด “2. ล็อกคู่ทั้งหมด” ก่อนตรวจ Preview','warn');return;}var previewRound=String(W121.roundId),previewSignature=w121PreviewSignature();w121Call('sendWeekly121Round',{roundId:previewRound,dryRun:true},function(r){if(!r.ok||previewRound!==String(W121.roundId)||previewSignature!==w121PreviewSignature())return;W121.previews=r.previews||[];var sample=W121.previews[0],blocked=r.suppressed||[],bad=r.unsendable||[],expected=(W121.pairs||[]).reduce(function(n,p){return n+(p.members||[]).length;},0),passed=Number(r.messageCount)===expected&&!blocked.length&&!bad.length,gate=document.getElementById('w121-send-readiness');W121.previewPassed=passed;W121.previewProof=passed?previewSignature:'';w121SetStep(passed?4:3);w121UpdateActionFlow();if(gate){gate.className='w121-inline-status '+(passed?'ready':'blocked');gate.textContent=passed?'✅ Preview ผ่าน '+r.messageCount+' / '+expected+' คน · พร้อมกด “4. ยืนยันและส่ง LINE”':'⛔ ยังส่งไม่ได้ · พร้อม '+r.messageCount+' / '+expected+' · ระงับ '+blocked.length+' · ไม่มี LINE '+bad.length;}alert((passed?'✅ PREVIEW ผ่าน — ยังไม่มีการส่ง LINE':'⛔ PREVIEW ยังไม่ผ่าน — ไม่มีการส่ง LINE')+'\n\nพร้อมส่ง: '+r.messageCount+' / '+expected+'\nระบบระงับ: '+blocked.length+(blocked.length?' ('+blocked.map(function(x){return x.name+': '+x.reason;}).join(', ')+')':'')+'\nส่งไม่ได้: '+bad.length+(sample?'\n\nตัวอย่างข้อความ:\n'+sample.message:''));});}
function w121TestSend(){if(!W121.roundId){toast('ยังไม่มีรอบจับคู่','warn');return;}w121Call('sendWeekly121Round',{roundId:W121.roundId,dryRun:true,testMode:true},function(pre){if(!pre.ok)return;var bad=pre.unsendable||[],blocked=pre.suppressed||[];var msg='🧪 ส่งข้อความทดสอบให้สมาชิกในรอบนี้?\n\nข้อความทุกฉบับจะขึ้นต้นว่า “นี่คือการทดลองระบบ”\nพร้อมส่ง: '+pre.messageCount+'\nระบบระงับ: '+blocked.length+'\nส่งไม่ได้: '+bad.length+(bad.length?' ('+bad.join(', ')+')':'')+'\n\nระบบจะป้องกันการกดส่งทดสอบซ้ำในรอบเดิม';if(!confirm(msg))return;w121Call('sendWeekly121Round',{roundId:W121.roundId,dryRun:false,testMode:true,confirmed:true},function(r){if(r.ok)toast('ทดสอบสำเร็จ '+r.sent+' · ป้องกัน/ข้าม '+r.skipped+' · ล้มเหลว '+r.failed,r.failed?'warn':'ok');});});}
function w121LiveLabel(status){return{queued:'รอส่ง',pending:'LINE กำลังรับ',sent:'LINE รับคำขอแล้ว',failed:'ส่งไม่สำเร็จ',skipped:'ระบบข้าม'}[status]||status;}
function w121RenderLiveDelivery(r){var c=r.counts||{},wait=Number(c.queued||0)+Number(c.pending||0),bad=Number(c.failed||0)+Number(c.skipped||0),done=Number(c.sent||0)+bad,total=Number(r.total||0);document.getElementById('w121-live-total').textContent=total;document.getElementById('w121-live-sent').textContent=Number(c.sent||0);document.getElementById('w121-live-wait').textContent=wait;document.getElementById('w121-live-failed').textContent=bad;document.getElementById('w121-live-bar').style.width=(total?Math.round(done/total*100):0)+'%';document.getElementById('w121-live-list').innerHTML=(r.recipients||[]).map(function(x){var status=String(x.status||'queued'),detail=x.lastError?' · '+esc(String(x.lastError).slice(0,90)):x.sentAt?' · '+new Date(x.sentAt).toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'';return'<div class="w121-live-person"><div><b>'+esc(x.name)+'</b><small>คู่กับ '+esc(x.partner||'—')+(status==='failed'&&x.lastError?'<br>'+esc(String(x.lastError).slice(0,90)):'')+'</small></div><span class="w121-live-state '+esc(status)+'">'+esc(w121LiveLabel(status))+esc(detail)+'</span></div>';}).join('');var terminal=['sent','partially_failed','cancelled'].includes(String(r.roundStatus))&&wait===0;if(terminal){clearInterval(W121.liveTimer);W121.liveTimer=null;document.getElementById('w121-live-close').disabled=false;document.getElementById('w121-live-title').textContent=bad?'ส่งผลจับคู่เสร็จ แต่มีรายการต้องตรวจ':'ส่งผลจับคู่ครบแล้ว';document.getElementById('w121-live-sub').textContent='อัปเดตล่าสุด '+new Date(r.serverTime).toLocaleTimeString('th-TH');if(W121.liveRefreshedRound!==String(r.roundId)){W121.liveRefreshedRound=String(r.roundId);w121RefreshDashboards();}}}
function w121PollLiveDelivery(){if(!W121.liveRoundId)return;w121Call('getWeekly121DeliveryLive',{roundId:W121.liveRoundId},function(r){if(r.ok)w121RenderLiveDelivery(r);});}
function w121OpenLiveDelivery(roundId){W121.liveRoundId=roundId;W121.liveRefreshedRound='';clearInterval(W121.liveTimer);var shade=document.getElementById('w121-live-shade');shade.hidden=false;document.body.style.overflow='hidden';document.getElementById('w121-live-close').disabled=true;document.getElementById('w121-live-title').textContent='กำลังส่งผลจับคู่ 1-2-1';document.getElementById('w121-live-sub').textContent='หน้าจอนี้อัปเดตอัตโนมัติทุก 0.8 วินาที';w121PollLiveDelivery();W121.liveTimer=setInterval(w121PollLiveDelivery,800);}
function w121ViewLiveDelivery(roundId){W121.roundId=roundId;w121OpenLiveDelivery(roundId);}
function w121CloseLiveDelivery(){if(document.getElementById('w121-live-close').disabled)return;clearInterval(W121.liveTimer);W121.liveTimer=null;W121.liveRoundId='';document.getElementById('w121-live-shade').hidden=true;document.body.style.overflow='';w121RefreshDashboards({reloadRound:true});}
function w121Send(){if(!W121.roundId){toast('ยังไม่มีรอบจับคู่','warn');return;}if(!W121.previewPassed){toast('กรุณากด “3. ตรวจ Preview” ให้ผ่านก่อนส่งจริง','warn');return;}w121Call('sendWeekly121Round',{roundId:W121.roundId,dryRun:true},function(pre){if(!pre.ok)return;var bad=pre.unsendable||[],blocked=pre.suppressed||[],expected=(W121.pairs||[]).reduce(function(n,p){return n+(p.members||[]).length;},0),pairs=W121.pairs.length;var msg='ยืนยันส่ง LINE จริง?\n\nพร้อมส่ง: '+pre.messageCount+' / '+expected+' คน\nจำนวนคู่: '+pairs+'\nระบบระงับ: '+blocked.length+(blocked.length?' ('+blocked.map(function(x){return x.name+': '+x.reason;}).join(', ')+')':'')+'\nส่งไม่ได้: '+bad.length+(bad.length?' ('+bad.join(', ')+')':'');if(!pairs||Number(pre.messageCount)!==expected||blocked.length||bad.length){W121.previewPassed=false;w121UpdateActionFlow();alert('⛔ ยังส่ง LINE จริงไม่ได้\n\n'+msg+'\n\nกรุณาแก้ Pilot, LINE หรือ Message Guard ให้พร้อมครบทุกคนก่อน');return;}msg+='\n\nDry-run ผ่านครบทุกคนแล้ว\nหลังยืนยัน ระบบจะเปิดหน้าติดตามสถานะรายคนแบบสด';if(!confirm(msg))return;var activeRound=W121.roundId;w121OpenLiveDelivery(activeRound);w121Call('sendWeekly121Round',{roundId:activeRound,dryRun:false,confirmed:true},function(r){if(!r.ok){clearInterval(W121.liveTimer);W121.liveTimer=null;document.getElementById('w121-live-close').disabled=false;document.getElementById('w121-live-title').textContent='ไม่สามารถเริ่มส่งได้';return;}w121PollLiveDelivery();toast('ส่งสำเร็จ '+r.sent+' · ป้องกัน/ข้าม '+r.skipped+' · ล้มเหลว '+r.failed,(r.failed||r.skipped)?'warn':'ok');w121RefreshDashboards();});});}

var w121SendAfterValidPreview=w121Send;
w121Send=function(){if(!w121HasValidPreview()){w121InvalidatePreview();w121UpdateActionFlow();toast('กรุณากด “3. ตรวจ Preview” ให้ผ่านก่อนส่งจริง','warn');return;}w121SendAfterValidPreview();};

document.addEventListener('visibilitychange',function(){if(!document.hidden&&document.getElementById('mc-w121')&&document.getElementById('mc-w121').classList.contains('on'))w121RefreshDashboards();});
function w121LoadHistory(force){var el=document.getElementById('w121-history');if(!el)return;if(!force&&el.dataset.loaded)return;el.textContent='⏳ กำลังโหลดรอบที่ผ่านมา...';w121Call('getWeekly121History',{},function(r){if(!r.ok){el.textContent=r.error||'';return;}el.dataset.loaded='1';var labels={draft:'ร่าง',confirmed:'ยืนยันแล้ว',sending:'กำลังส่ง',sent:'ส่งแล้ว',partially_failed:'ส่งไม่ครบ',cancelled:'ยกเลิกแล้ว'};el.innerHTML=(r.rounds||[]).map(function(x){var count=x.matching_pairs&&x.matching_pairs[0]?x.matching_pairs[0].count:0,created=x.created_at?new Date(x.created_at).toLocaleString('th-TH',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'',delivery=['sent','partially_failed','sending'].includes(x.status)?'<button class="w121-icon-btn" style="color:#34d399" onclick="event.stopPropagation();w121ViewLiveDelivery(\''+x.id+'\')">ดูผลส่ง</button>':'',action=x.status==='draft'?'<button class="w121-icon-btn" style="color:var(--re)" onclick="event.stopPropagation();w121DeleteDraft(\''+x.id+'\')">ลบรอบทดสอบ</button>':['sent','partially_failed','sending','confirmed'].includes(x.status)?'<button class="w121-icon-btn" style="color:#fbbf24" onclick="event.stopPropagation();w121CancelRound(\''+x.id+'\')">ยกเลิกและสร้างใหม่</button>':'';return '<div class="w121-history-item" style="cursor:pointer" onclick="w121Open(\''+x.id+'\')"><b>'+esc(x.meeting_date)+'</b><span>'+count+' คู่ · '+esc(x.source_file_name||'ไม่ระบุไฟล์')+'<br><small>'+esc(created)+'</small></span><div style="display:flex;gap:6px;align-items:center;justify-content:flex-end;flex-wrap:wrap"><span style="color:'+(x.status==='sent'?'#06C755':x.status==='partially_failed'||x.status==='cancelled'?'var(--re)':'var(--sub)')+'">'+esc(labels[x.status]||x.status)+'</span>'+delivery+action+'</div></div>';}).join('')||'<div class="w121-empty">ยังไม่มีรอบจับคู่<br><span style="font-size:10px">นำเข้า CSV เพื่อสร้างรอบแรก</span></div>';});}
function w121DeleteDraft(roundId){if(!confirm('ลบรอบทดสอบนี้ถาวร?\n\nทำได้เฉพาะรอบที่ยังไม่เคยส่ง LINE และจะลบคู่/ไฟล์นำเข้าของรอบนี้ด้วย'))return;w121Call('deleteWeekly121Draft',{roundId:roundId},function(r){if(!r.ok)return;if(W121.roundId===roundId){W121.roundId='';W121.pairs=[];document.getElementById('w121-work').style.display='none';}var el=document.getElementById('w121-history');if(el)delete el.dataset.loaded;w121LoadHistory(true);toast('ลบรอบทดสอบแล้ว','ok');});}
function w121CancelRound(roundId){var reason=prompt('เหตุผลที่ยกเลิกรอบนี้','ส่งหรือจับคู่ผิด');if(reason===null)return;if(!confirm('ยืนยันยกเลิกรอบที่ส่งแล้ว และสร้างรอบร่างใหม่จากข้อมูลเดิม?\n\nข้อความ LINE ที่ส่งไปแล้วเรียกคืนไม่ได้ แต่คู่เดิมจะถูกยกเลิกและเก็บไว้ในประวัติ'))return;w121Call('cancelWeekly121Round',{roundId:roundId,reason:reason,createReplacement:true},function(r){if(!r.ok)return;var el=document.getElementById('w121-history');if(el)delete el.dataset.loaded;w121LoadHistory(true);w121LoadOverview();if(r.replacementRoundId){toast('ยกเลิกรอบเดิมและสร้างรอบใหม่แล้ว','ok');w121Open(r.replacementRoundId);}else toast('ยกเลิกรอบแล้ว','ok');});}
